target.css:
:root {
  --ink: #18323a;
  --paper: #fffdf6;
  --line: #cbd9d4;
  --mist: #edf4ef;
  --teal: #167c78;
  --aqua: #56bdb5;
  --lime: #c9df71;
  --coral: #ec7665;
  --muted: #668087;
}

* {
  box-sizing: border-box;
}

.seismic-card {
  width: 500px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.card-head {
  min-height: 68px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  border-bottom: 1px solid var(--line);
}

.title-block {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.eyebrow {
  margin: 0;
  color: var(--teal);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.3px;
}

h1 {
  margin: 0;
  font-size: 20px;
  line-height: 1.1;
  letter-spacing: -0.4px;
}

.status {
  padding: 6px 9px;
  color: var(--teal);
  background: var(--lime);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.8px;
}

.dashboard {
  display: grid;
  grid-template-columns: 1.08fr 0.92fr;
  gap: 12px;
  padding: 14px 16px;
}

.trace-panel {
  min-width: 0;
  margin: 0;
  padding: 11px 12px 8px;
  background: var(--mist);
  border: 1px solid var(--line);
  border-radius: 12px;
}

.trace-panel figcaption,
.panel-label,
.card-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.trace-panel figcaption {
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.8px;
}

.trace-panel figcaption strong {
  color: var(--teal);
  font-size: 10px;
}

.trace-bars {
  height: 66px;
  display: flex;
  align-items: center;
  gap: 4px;
  margin: 7px 0 4px;
  padding: 0;
  list-style: none;
  border-top: 1px dashed var(--line);
  border-bottom: 1px dashed var(--line);
}

.trace-bars li {
  flex: 1;
  height: 8px;
  background: var(--aqua);
  border-radius: 5px;
}

.trace-bars li:nth-child(2),
.trace-bars li:nth-child(8) { height: 25px; }
.trace-bars li:nth-child(3),
.trace-bars li:nth-child(7) { height: 43px; background: var(--teal); }
.trace-bars li:nth-child(4),
.trace-bars li:nth-child(6) { height: 18px; }
.trace-bars li:nth-child(5) { height: 57px; background: var(--coral); }
.trace-bars li:nth-child(9) { height: 30px; }
.trace-bars li:nth-child(10) { height: 13px; }
.trace-bars li:nth-child(11) { height: 21px; }
.trace-bars li:nth-child(12) { height: 9px; }

.trace-scale {
  display: flex;
  justify-content: space-between;
  margin: 0;
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
}

.readings {
  padding: 11px 12px;
  background: var(--ink);
  border-radius: 12px;
}

.panel-label {
  padding-bottom: 8px;
  color: var(--paper);
  border-bottom: 1px solid var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.8px;
}

.dot {
  color: var(--lime);
  font-size: 9px;
}

.readings dl {
  display: grid;
  gap: 7px;
  margin: 9px 0 0;
}

.reading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}

.reading dt {
  color: var(--line);
  font-size: 11px;
}

.reading dd {
  margin: 0;
  color: var(--paper);
  font-size: 14px;
  font-weight: 800;
}

.reading small {
  color: var(--aqua);
  font-size: 10px;
}

.card-foot {
  min-height: 52px;
  padding: 9px 16px;
  background: var(--mist);
  border-top: 1px solid var(--line);
}

.card-foot p {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
}

.pin {
  color: var(--coral);
}

button {
  padding: 8px 11px;
  color: var(--paper);
  background: var(--teal);
  border: 0;
  border-radius: 7px;
  font-size: 11px;
  font-weight: 800;
}

